export function bankFallbacks (lines) {
  if (!Array.isArray(lines)) return 0
  let n = 0
  for (const l of lines) {
    if (typeof l === 'string' && BANK_FALLBACK_RE.test(l)) n++
  }
  return n
}

export function bankFallbackTrendConsistent (e) {
  if (!e || typeof e !== 'object' || Array.isArray(e)) return false
  const faceOk = (s) => {
    if (!s || typeof s !== 'object' || Array.isArray(s)) return false
    return Number.isInteger(s.bankFallbacks) && s.bankFallbacks >= 0
  }
  return faceOk(e.back) && faceOk(e.prev) && faceOk(e.cur)
}

